package com.csust.eyediagnosis.workflow.graph.runtime;
import com.csust.eyediagnosis.workflow.domain.ExplanationPublicationStatus; import com.csust.eyediagnosis.workflow.explanation.ExplanationPublicationDecision; import com.csust.eyediagnosis.workflow.explanation.ExplanationValidationStatus; import com.csust.eyediagnosis.workflow.persistence.entity.WorkflowNodeExecutionEntity; import com.csust.eyediagnosis.workflow.persistence.repository.ExplanationSnapshotRepository; import com.csust.eyediagnosis.workflow.persistence.repository.NodeExecutionRepository; import org.springframework.dao.DuplicateKeyException; import org.springframework.stereotype.Component; import java.time.LocalDateTime;
/** Persistence-only writer; it never calls a model, validator, retriever, or review service. */
@Component public final class ExplanationSnapshotDeltaWriter implements SegmentBusinessDeltaWriter<ExplanationSnapshotDelta> { private final ExplanationSnapshotRepository snapshots; private final NodeExecutionRepository nodes; public ExplanationSnapshotDeltaWriter(ExplanationSnapshotRepository snapshots,NodeExecutionRepository nodes){this.snapshots=snapshots;this.nodes=nodes;} public Class<ExplanationSnapshotDelta> supportedType(){return ExplanationSnapshotDelta.class;} public void write(ExplanationSnapshotDelta delta){ var snapshot=snapshots.findByWorkflowIdAndRevision(delta.snapshot().getWorkflowId(),delta.snapshot().getRevision()).orElseGet(()->insert(delta)); transition(snapshot,delta); for(NodeExecutionCompletion completion:delta.nodeExecutions()) complete(completion); } private com.csust.eyediagnosis.workflow.persistence.entity.ExplanationSnapshotEntity insert(ExplanationSnapshotDelta delta){try{if(snapshots.insert(delta.snapshot())!=1)throw new IllegalStateException("explanation snapshot was not persisted");return delta.snapshot();}catch(DuplicateKeyException exception){return snapshots.findByWorkflowIdAndRevision(delta.snapshot().getWorkflowId(),delta.snapshot().getRevision()).orElseThrow(()->exception);}} private void transition(com.csust.eyediagnosis.workflow.persistence.entity.ExplanationSnapshotEntity snapshot,ExplanationSnapshotDelta delta){String target=switch(delta.decision()){case PUBLISH->{if(delta.validation().status()!=ExplanationValidationStatus.VALIDATED)throw new IllegalStateException("unvalidated explanation cannot publish");yield ExplanationPublicationStatus.PUBLISHED.name();}case COMPLETE_LIMITED->delta.validation().status()==ExplanationValidationStatus.REJECTED?ExplanationPublicationStatus.REJECTED.name():ExplanationPublicationStatus.WITHHELD.name();case WITHHOLD->ExplanationPublicationStatus.WITHHELD.name();case FINAL_REVIEW_REQUIRED->ExplanationPublicationStatus.VALIDATED.name();};if(target.equals(snapshot.getPublicationStatus()))return;if(snapshots.updatePublicationStatusIfExpected(snapshot.getWorkflowId(),snapshot.getRevision(),snapshot.getPublicationStatus(),target)!=1)throw new IllegalStateException("explanation snapshot status transition failed");} private void complete(NodeExecutionCompletion completion){WorkflowNodeExecutionEntity node=new WorkflowNodeExecutionEntity();node.setNodeExecutionId(completion.nodeExecutionId());node.setStatus("COMPLETED");node.setOutputDigest(completion.outputDigest());node.setResultReference(completion.resultReference());node.setCompletedAt(LocalDateTime.now());node.setUpdatedAt(LocalDateTime.now());if(nodes.complete(node)!=1)throw new IllegalStateException("explanation node execution was not completed");} }
